export function TouchTarget({
  undersizedSize = {{undersizedSize}},
  showGuide = {{showGuide}},
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  const frame = (guide) => ({ display: "grid", placeItems: "center", width: 44, height: 44, outline: guide ? "1.5px dashed #24143066" : "none", outlineOffset: 2 });
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 11, color: "#241430aa", display: "flex", gap: 20, flexWrap: "wrap" }}>
      <div style={{ textAlign: "center" }}>
        <div style={frame(showGuide)}><button type="button" style={{ width: 44, height: 44, borderRadius: 999, border: "none", color: "#241430", fontWeight: 700, cursor: "pointer", background: accent }}>&#10003;</button></div>
        <p style={{ margin: "8px 0 0", maxWidth: 100 }}>44&times;44px &mdash; meets the minimum</p>
      </div>
      <div style={{ textAlign: "center" }}>
        <div style={frame(showGuide)}><button type="button" style={{ width: undersizedSize, height: undersizedSize, borderRadius: 999, border: "none", color: "#241430", fontWeight: 700, cursor: "pointer", background: accent }}>&#10003;</button></div>
        <p style={{ margin: "8px 0 0", maxWidth: 100 }}>{undersizedSize}&times;{undersizedSize}px &mdash; too small to tap reliably</p>
      </div>
      <p style={{ flexBasis: "100%", margin: 0 }}>"{label}" as two hit-target sizes, guide ring shows the 44px reference</p>
    </div>
  );
}
